SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>CustTable</c> field DlvMode.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, DlvMode))]
internal class GUPPricingAttributeCustTableDlvMode extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, DlvMode);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    DlvMode dlvMode;

    while select DlvMode from custtable
        group by DlvMode
        join dlvMode
        group by Code, Txt
        where custTable.DlvMode == dlvMode.Code
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(dlvMode.Code, dlvMode.Txt);
        ret.add(valueObject);
    }
    return ret;
}
